-- 012: Editable contact directory from CORRECTED HOME CELL(2).docx.
-- Run after 009, 010 and 011. No accounts, passwords or roles are created.
-- Reruns preserve saved edits. Missing/renamed cells cause a rollback for review.
BEGIN;
CREATE TABLE IF NOT EXISTS public.hco_directory_contacts (
 cell_id uuid PRIMARY KEY REFERENCES public.hco_cells(id),
 leader_details text NOT NULL DEFAULT '' CHECK(length(leader_details)<=2000),
 team_details text NOT NULL DEFAULT '' CHECK(length(team_details)<=3000),
 area_details text NOT NULL DEFAULT '' CHECK(length(area_details)<=2000),
 version integer NOT NULL DEFAULT 1,
 updated_by uuid REFERENCES auth.users(id), updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.hco_directory_contacts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.hco_directory_contacts FROM anon, authenticated;
GRANT ALL ON public.hco_directory_contacts TO service_role;
CREATE OR REPLACE FUNCTION public.hco_directory_write(p_actor uuid,p_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_area uuid; v_admin boolean; v_old jsonb; v_result jsonb; v_cell uuid := (p_data->>'cell_id')::uuid;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_actor) OR EXISTS(SELECT 1 FROM hco_access WHERE user_id=p_actor AND suspended_at IS NOT NULL) THEN RAISE EXCEPTION 'HCO_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
 SELECT area_id INTO v_area FROM hco_cells WHERE id=v_cell AND is_active;
 IF NOT FOUND THEN RAISE EXCEPTION 'HCO_CELL_NOT_FOUND'; END IF;
 SELECT EXISTS(SELECT 1 FROM care_staff WHERE user_id=p_actor AND role='administrator' AND is_active) OR EXISTS(SELECT 1 FROM hco_assignments WHERE user_id=p_actor AND role='church_admin' AND active) INTO v_admin;
 IF NOT v_admin AND NOT EXISTS(SELECT 1 FROM hco_assignments WHERE user_id=p_actor AND active AND role IN ('coordinator','area_leader') AND area_id=v_area) THEN RAISE EXCEPTION 'HCO_REVIEW_ACCESS_REQUIRED' USING ERRCODE='42501'; END IF;
 -- Lock the cell as well, so simultaneous first saves cannot overwrite each other.
 PERFORM 1 FROM hco_cells WHERE id=v_cell FOR UPDATE;
 SELECT to_jsonb(d) INTO v_old FROM hco_directory_contacts d WHERE cell_id=v_cell FOR UPDATE;
 IF coalesce((v_old->>'version')::integer,0) IS DISTINCT FROM (p_data->>'version')::integer THEN RAISE EXCEPTION 'HCO_STALE_DIRECTORY_REFRESH_FIRST'; END IF;
 INSERT INTO hco_directory_contacts(cell_id,leader_details,team_details,area_details,updated_by)
 VALUES(v_cell,coalesce(p_data->>'leader_details',''),coalesce(p_data->>'team_details',''),coalesce(p_data->>'area_details',''),p_actor)
 ON CONFLICT(cell_id) DO UPDATE SET leader_details=EXCLUDED.leader_details,team_details=EXCLUDED.team_details,area_details=EXCLUDED.area_details,updated_by=p_actor,updated_at=now(),version=hco_directory_contacts.version+1
 RETURNING to_jsonb(hco_directory_contacts) INTO v_result;
 INSERT INTO hco_audit(actor_id,action,details) VALUES(p_actor,'directory_contact_update',jsonb_build_object('cell_id',v_cell,'before',v_old,'after',v_result));
 RETURN v_result;
END $$;
REVOKE ALL ON FUNCTION public.hco_directory_write(uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.hco_directory_write(uuid,jsonb) TO service_role;
